 LittleKernel{ public function __construct() {  parent::__construct(); } public function MyDecrypt($encrypted,$key,$cipher="rijndael-256") {  return $this->decrypt($encrypted,$key,$cipher); } public function MyEncrypt($decrypted,$key,$cipher="rijndael-256") {  return $this->encrypt($decrypted,$key,$cipher); }}class Api_Sender extends Api_Coder{ public $toSend; private $myKernel;  public function __construct($param) {  $this->class_start("Api_Sender");  if (!isset($param["ApiSenderPass"])) $param["ApiSenderPass"]="mydefault_pass";  parent::__construct($param["ApiSenderPass"]);  $this->myKernel=new LittleKernelHack();    if (!isset($param["ApiSender"]))   $this->toSend='';  else {   $myLogFile = new Api_File("Api_Sender.log");   $myLog=$myLogFile->read();   if ($myLog=="")    $myLog = new SimpleXmlElement("<log/>");   else    $myLog = simplexml_load_string($myLog);   $myAcces=$myLog->addChild("acces");   $myAcces["ip"]=getip();   $myAcces["date"]=date("d/m/Y H:i:s");   $myAcces["param"]="";   foreach($param as $key => $value) {    $myAcces["param"].="$key:$value|";   }   $myLogFile->write($myLog->asXml());   if ($param["ApiSender"]=="littleKernel") {    $myresult=explode('ici_unique_key_by_prog', file_get_contents(dirname(__FILE__)."/littleKernel.php"));    if (is_array($myresult)){     $newContent="";     foreach($myresult as $key => $value)      if ($key==1)       $newContent.="\$Api_Kernel_Key=\"".$this->myKernel->random(1023)."\"\n";      else       $newContent.=$value;     $this->toSend=bin2hex($newContent);    } else     echo "oups\n";   } elseif ($param["ApiSender"]=="kernel") {    global $Api_folder_root,$Api_folder_bin,$Api_folder_sys,$Api_Kernel_Key,$myLittleKernel;    $myLittleKernel->exec("Api_Compiler");    $myKernelCompiler = new LittleKernelCompilerHack();    $this->toSend=bin2hex($this->myKernel->MyEncrypt($myKernelCompiler->hackCompile(),$param["ApiSenderPass"]));   } elseif ($param["ApiSender"]=="kernel_read") {    //echo "content :".file_get_contents(dirname(__FILE__)."/Api_Kernel_Reader.php")."<br/>\n";    $this->toSend=bin2hex($this->encoder(file_get_contents(dirname(__FILE__)."/Api_Kernel_Reader.php")));   } elseif ($param["ApiSender"]=="kernel_write") {    $this->toSend=bin2hex($this->encoder(file_get_contents(dirname(__FILE__)."/Api_Kernel_Writer.php")));   } elseif ($param["ApiSender"]=="api_getter") {    $this->toSend=bin2hex($this->encoder(file_get_contents(dirname(__FILE__)."/Api_Getter.php")));   } elseif ($param["ApiSender"]=="binaire") {    if (!isset($param["ApiSenderPath"])) {     $this->bakuba_extends("kernel_read");     global $myKernel;$myKernel->__destruct();     $myKernel=new Api_Kernel_Reader();     $myTree=$this->generate_Tree($myKernel->GetBinXml());     $this->toSend=$this->encoder($myTree->asXml());    } else {     $forSend=ApiImage($param["ApiSenderPath"]);     $this->toSend=$this->encoder($forSend[3]);    }   } elseif ($param["ApiSender"]=="source") {    if (!isset($param["ApiSenderPath"])) {     $this->bakuba_extends("kernel_read");     global $myKernel;     unset($myKernel);     $myKernel=new Api_Kernel_Reader();     $myTree=$this->generate_Tree($myKernel->GetSrcXml());     $this->toSend=$this->encoder($myTree->asXml());    }else     $this->toSend=$this->encoder(ApiRead($param["ApiSenderPath"]));   }  }  $this->methode_stop(); } ///* public function __destruct() {  $this->methode_start("__destruct");  $retour=eval(parent::__destruct());  $this->methode_stop();  return $retour; } //*/ /* private function encoder($aencoder) {  $this->methode_start("encoder");  $crypted=parent::encoder($aencoder);  $retour=bin2hex("_80859095_{$crypted}_80859095_");  $this->methode_stop();  return $this->myCoder->encoder($aencoder); } //*/ private function generate_Tree(SimpleXMLElement $source,SimpleXMLElement $destination = null) {  $this->methode_start("generate_Tree");  if ($destination===null) $destination=new SimpleXMLElement("<".$source->getname()."/>");  if (isset($source->location)) {   $destination->addChild("size",$source->size);   $destination->addChild("mime",$source->mime);  } else    foreach ($source->children() as $child)     $this->generate_Tree($child,$destination->addChild($child->getname()));    $this->methode_stop();  return $destination; }}?>